import type { FormEvent } from "react";
import type { WidgetStorageScope } from "@homarr/widget-sdk";
type ChecklistItem = {id:string;label:string;done:boolean};
import { Alert, Button, Checkbox, Group, Stack, Text, TextInput } from "@mantine/core";
import { useWidgetCommands, useWidgetHost, useWidgetOptions, useWidgetState, useWidgetStorage } from "@homarr/widget-sdk";
export default function Checklist() {
  const host = useWidgetHost();
  const options = useWidgetOptions<{title:string;scope:WidgetStorageScope}>();
  const [draft, setDraft] = useWidgetState("draft", "");
  const stored = useWidgetStorage<ChecklistItem[]>(options.scope, "checklist-v1", []);
  const items = Array.isArray(stored.data) ? stored.data : [];
  const locked = host.isEditMode || stored.isPending || stored.saving;
  const save = (value:ChecklistItem[]) => { void stored.set(value).catch(() => undefined); };
  useWidgetCommands([{ id: "clear-completed", label: "Clear completed items", disabled: locked || !items.some((item) => item.done), run: () => save(items.filter((item) => !item.done)) }]);
  const add = (event:FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!draft.trim() || locked) return; save([...items, { id: crypto.randomUUID(), label: draft.trim(), done: false }]); setDraft(""); };
  return <Stack p="md" gap="sm" h="100%" style={{ overflow: "auto" }}>
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Text size="sm" c="dimmed">{items.filter((item) => item.done).length}/{items.length}</Text></Group>
    {(stored.error || stored.saveError) && <Alert color="red">{stored.error?.message ?? stored.saveError?.message}</Alert>}
    {items.map((item) => <Checkbox key={item.id} label={item.label} checked={item.done} disabled={locked} onChange={() => save(items.map((row) => row.id === item.id ? { ...row, done: !row.done } : row))} />)}
    {!items.length && !stored.isPending && <Text c="dimmed" size="sm">Add your first maintenance task.</Text>}
    <form onSubmit={add}><Group wrap="nowrap"><TextInput aria-label="New task" placeholder="New task" value={draft} onChange={(event) => setDraft(event.currentTarget.value)} style={{ flex: 1 }} /><Button type="submit" disabled={locked || !draft.trim()}>Add</Button></Group></form>
    {host.displayMode === "advanced" && <Text size="xs" c="dimmed">Changes are saved to Homarr. The selected storage scope controls whether this checklist belongs to you, this tile, or every placement of this installation.</Text>}
  </Stack>;
}
